import re
import pandas as pd
from datetime import datetime


_NUM_RE = re.compile(r'^[+-]?\d+(\.\d{1,2})?$')
_DATE_RE = re.compile(r'^\d{4}-\d{2}-\d{2}$')


def _is_null(v):
    return v is None or (isinstance(v, float) and pd.isna(v)) or pd.isna(v)


def run(inputs: dict) -> dict:
    df = inputs['raw_payments']

    valid_rows = []
    reject_rows = []

    # First pass: apply R1-R5, collect survivors for duplicate check
    survivors = []  # list of dicts with parsed values, row_num, trimmed payment_id

    for _, row in df.iterrows():
        row_num = row['row_num']
        payment_id = row['payment_id']
        account_id = row['account_id']
        amount_txt = row['amount_txt']
        currency = row['currency']
        pay_date_txt = row['pay_date_txt']

        # R1 MISSING_ID
        if _is_null(payment_id):
            reject_rows.append((row_num, 'MISSING_ID'))
            continue
        pid_trim = str(payment_id).strip()
        if pid_trim == '':
            reject_rows.append((row_num, 'MISSING_ID'))
            continue

        # R2 BAD_AMOUNT
        if _is_null(amount_txt):
            reject_rows.append((row_num, 'BAD_AMOUNT'))
            continue
        amt_trim = str(amount_txt).strip()
        if not _NUM_RE.match(amt_trim):
            reject_rows.append((row_num, 'BAD_AMOUNT'))
            continue
        try:
            parsed_amount = float(amt_trim)
        except ValueError:
            reject_rows.append((row_num, 'BAD_AMOUNT'))
            continue

        # R3 NON_POSITIVE
        if parsed_amount <= 0:
            reject_rows.append((row_num, 'NON_POSITIVE'))
            continue

        # R4 BAD_CURRENCY
        if _is_null(currency):
            reject_rows.append((row_num, 'BAD_CURRENCY'))
            continue
        cur_trim = str(currency).strip().upper()
        if cur_trim not in ('USD', 'EUR', 'GBP'):
            reject_rows.append((row_num, 'BAD_CURRENCY'))
            continue

        # R5 BAD_DATE
        if _is_null(pay_date_txt):
            reject_rows.append((row_num, 'BAD_DATE'))
            continue
        date_trim = str(pay_date_txt).strip()
        if not _DATE_RE.match(date_trim):
            reject_rows.append((row_num, 'BAD_DATE'))
            continue
        try:
            parsed_date = datetime.strptime(date_trim, '%Y-%m-%d').date()
        except ValueError:
            reject_rows.append((row_num, 'BAD_DATE'))
            continue

        survivors.append({
            'row_num': row_num,
            'payment_id': pid_trim,
            'account_id': account_id,
            'amount': parsed_amount,
            'currency': cur_trim,
            'pay_date': parsed_date,
        })

    # R6 DUPLICATE: group survivors by trimmed payment_id, keep lowest row_num
    best_row_num = {}
    for s in survivors:
        pid = s['payment_id']
        if pid not in best_row_num or s['row_num'] < best_row_num[pid]:
            best_row_num[pid] = s['row_num']

    for s in survivors:
        pid = s['payment_id']
        if s['row_num'] == best_row_num[pid]:
            valid_rows.append(s)
        else:
            reject_rows.append((s['row_num'], 'DUPLICATE'))

    valid_payments = pd.DataFrame(
        valid_rows,
        columns=['row_num', 'payment_id', 'account_id', 'amount', 'currency', 'pay_date']
    )
    if not valid_payments.empty:
        valid_payments = valid_payments.sort_values('row_num').drop(columns=['row_num']).reset_index(drop=True)
    else:
        valid_payments = pd.DataFrame(columns=['payment_id', 'account_id', 'amount', 'currency', 'pay_date'])

    payment_rejects = pd.DataFrame(reject_rows, columns=['row_num', 'reject_reason'])
    if not payment_rejects.empty:
        payment_rejects = payment_rejects.sort_values('row_num').reset_index(drop=True)

    return {
        'valid_payments': valid_payments,
        'payment_rejects': payment_rejects,
    }
